arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -d "types=public_channel,private_channel&limit=1000&exclude_archived=false" | python3 -c "
import sys, json
d = json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR', d.get('error')); sys.exit()
for c in d.get('channels', []):
    n = c.get('name','')
    if 'incident' in n.lower() or 'outage' in n.lower():
        print(c.get('id'), '|', n, '| archived=', c.get('is_archived'), '| topic=', c.get('topic',{}).get('title',''))
"

